<?php
require_once __DIR__ . '/config/database.php'; require_once __DIR__ . '/includes/functions.php'; require_login();
$stmt=$pdo->prepare("SELECT o.*,u.name AS seller_name,u.email AS seller_email FROM orders o JOIN users u ON u.id=o.seller_id WHERE o.buyer_id=? ORDER BY o.created_at DESC"); $stmt->execute([(int)current_user()['id']]); $orders=$stmt->fetchAll();
$pageTitle='My Orders'; require __DIR__.'/includes/header.php';
?>
<section class="container order-page"><div class="section-heading"><div><span class="eyebrow">Your purchases</span><h2>My Orders</h2><p>Track order and payment status. Arrange delivery directly with the seller.</p></div></div>
<?php if(!$orders): ?><div class="empty-state"><h3>No orders yet</h3><p>Find a book you love and place your first order.</p><a class="button" href="index.php#books">Browse books</a></div><?php else: ?><div class="order-list"><?php foreach($orders as $o): ?><article class="order-card"><div class="order-top"><div><span class="eyebrow">Order #<?= (int)$o['id'] ?></span><h3><?= e($o['book_title']) ?></h3><p>Placed <?= e($o['created_at']) ?></p></div><strong class="price">₹<?= number_format((float)$o['amount'],2) ?></strong></div><div class="order-badges"><span class="status status-<?= e($o['order_status']==='cancelled'?'rejected':($o['order_status']==='completed'?'approved':'pending')) ?>">Order: <?= e(ucfirst($o['order_status'])) ?></span><span class="status <?= $o['payment_status']==='paid'?'status-approved':($o['payment_status']==='failed'?'status-rejected':'status-pending') ?>">Payment: <?= e(ucfirst($o['payment_status'])) ?></span></div><p><strong>Payment method:</strong> <?= $o['payment_method']==='cod'?'Cash on Delivery / pay seller':'Razorpay online payment' ?></p><p><strong>Seller:</strong> <?= e($o['seller_name']) ?> · <a href="mailto:<?= e($o['seller_email']) ?>"><?= e($o['seller_email']) ?></a></p><p><strong>Delivery address:</strong> <?= nl2br(e($o['delivery_address'])) ?></p><?php if($o['payment_method']==='razorpay' && $o['payment_status']!=='paid'): ?><div class="notice error">Payment is not verified as paid. If you closed checkout, contact the seller before making another payment.</div><?php endif; ?><a class="button button-small button-light" href="order.php?id=<?= (int)$o['id'] ?>">View order</a></article><?php endforeach; ?></div><?php endif; ?></section>
<?php require __DIR__.'/includes/footer.php'; ?>
